class Solution {
    public int[] twoSum(int[] nums, int target) {
        int[]res = new int[2];
        Map<Integer,Integer> cnt = new HashMap<>();
        for(int i = 0;i<nums.length;i++){
            if(cnt.containsKey(target-nums[i])){
                res[0] = cnt.get(target-nums[i]);
                res[1] = i;
                return res;
            }else{
                cnt.put(nums[i],i);
            }
        }
        return res;
    }
}
